products_plus.liquid:
{% assign title = section.settings.title %}
{% assign arrangement = section.settings.arrangement %}
{% assign collection = section.settings.collection %}
{% assign max_count = section.settings.max_count %}
{% assign product_hover_image = section.settings.product_hover_image %}
{% assign _image = '/themes/theme1/assets/image/44613f1sd54f.png' | img_url %}
{% if shop.env == 0 and collection.id == 0 %}
  {% comment %} 专辑ID空（C端没有选择专辑的情况） {% endcomment %}
  {% assign style = 'display: none;' %}
{% elsif shop.env == 0 and collections[collection.id].products.size == 0 %}
  {% comment %} 专辑ID不空，但是商品数量空（专辑存在） {% endcomment %}
  {% assign style = 'display: none;' %}
{% elsif shop.env == 0 and collections[collection.id].products.size == '' %}
  {% comment %} 专辑ID不空，但是商品数量无法获取（专辑被删除） {% endcomment %}
  {% assign style = 'display: none;' %}
{% endif %}
{% assign palette_key = title | downcase | replace: 'é', 'e' | replace: 'è', 'e' | replace: 'ê', 'e' | replace: 'à', 'a' | replace: 'ù', 'u' | replace: 'û', 'u' | replace: 'ç', 'c' %}
{% assign rail_palette = 'blue' %}
{% if palette_key contains 'planter' or palette_key contains 'plant' or palette_key contains 'garden' or palette_key contains 'jardin' %}
  {% assign rail_palette = 'green' %}
{% elsif palette_key contains 'kitchen' or palette_key contains 'dining' or palette_key contains 'cuisine' or palette_key contains 'table' %}
  {% assign rail_palette = 'orange' %}
{% elsif palette_key contains 'bath' or palette_key contains 'bain' %}
  {% assign rail_palette = 'sand' %}
{% elsif palette_key contains 'home' or palette_key contains 'decor' or palette_key contains 'maison' or palette_key contains 'deco' %}
  {% assign rail_palette = 'red' %}
{% endif %}
<section class="lidl-rail lidl-rail--{{rail_palette}}" style="{{style}}">
<div class="collection_wrapper container container-gap">
  {% comment %} 卡片标题 {% endcomment %}
  {% if title %}
    <div class="lidl-rail__header">
      <div>
        <div class="lidl-rail__eyebrow">Sélection hebdomadaire</div>
        {% include 'card_title', title: title %}
      </div>
      {% if section.settings.view_all and section.settings.collection.url %}
        <a href="{{ section.settings.collection.url }}" class="btn btn-primary lidl-rail__cta">Tout voir</a>
      {% endif %}
    </div>
  {% endif %}

  {% if collection.id != 0 %}
    {% assign products = collections[collection.id].products %}
    {% if max_count <= products.size %}
      {% assign size = max_count %}
    {% else %}
      {% assign size = products.size %}
    {% endif %}

    {% case size %}
      {% when 1 %}
        {% assign colMd="col-md-12" %}
      {% when 2 %}
        {% assign colMd="col-md-6" %}
      {% when 4 %}
        {% assign colMd="col-md-6"%}
    {% endcase %}

    <div class="row product_row common__product-row">
      {% case size %}
        {% when 0 %}
          {% if shop.env == 1 %}
            {% include 'mock' %}
          {% endif %}
        {% when 3 %}
          {% if arrangement == 'grid' %}
            {% for product in products limit:size %}
              {% if product.published %}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: product, image_size: '110%' %}
                </div>
              {% endif %}
            {% endfor %}
          {% else %}
            <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: products[0], image_size: '83%' %}</div>
            <div class="common__product-gap product_item {{arrangement}} col-md-3">
              <div>{% include 'product_plus', product: products[1], image_size: '110%' %}</div>
              <div>{% include 'product_plus', product: products[2], image_size: '110%' %}</div>
            </div>
          {% endif %}
        {% when 5 %}
          {% if arrangement == 'grid' %}
            {% for product in products limit:2 %}
              {% if product.published %}
                <div class="common__product-gap product_item {{arrangement}} col-md-6">
                  {% include 'product_plus', product: product, image_size: '110%' %}
                </div>
              {% endif %}
            {% endfor %}
            {% for product in products offset:2 limit:3 %}
              {% if product.published %}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: product, image_size: '110%' %}
                </div>
              {% endif %}
            {% endfor %}

          {% else %}
            <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: products[0], image_size: '83%' %}</div>
            <div class="common__product-gap product_item {{arrangement}} col-md-3">
              <div>{% include 'product_plus', product: products[1], image_size: '110%' %}</div>
              <div>{% include 'product_plus', product: products[2], image_size: '110%' %}</div>
            </div>
            <div class="common__product-gap product_item {{arrangement}} col-md-6">{% include 'product_plus', product: products[3], image_size: '110%' %}</div>
            <div class="common__product-gap product_item {{arrangement}} col-md-6">{% include 'product_plus', product: products[4], image_size: '110%' %}</div>
          {% endif %}
        {% when 6 %}
          {% if arrangement == 'grid' %}
            {% for product in products limit:size %}
              {% if product.published %}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: product, image_size: '110%' %}
                </div>
              {% endif %}
            {% endfor %}
          {% else %}
            <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: products[0], image_size: '83%' %}</div>
            <div class="common__product-gap product_item {{arrangement}} col-md-3">
              <div>{% include 'product_plus', product: products[1], image_size: '110%' %}</div>
              <div>{% include 'product_plus', product: products[2], image_size: '110%' %}</div>
            </div>
            <div class="common__product-gap product_item {{arrangement}} col-md-3">
              <div>{% include 'product_plus', product: products[3], image_size: '110%' %}</div>
              <div>{% include 'product_plus', product: products[4], image_size: '110%' %}</div>
            </div>
            <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: products[5], image_size: '83%' %}</div>
          {% endif %}
        {% else %}
          {% for product in products limit:size %}
            {% if product.published %}
              <div class="common__product-gap product_item {{arrangement}} col-6 col-md-3">
                {% if size == 1 %}
                  {% assign ratio = '50%' %}
                {% else %}
                  {% assign ratio = '110%' %}
                {% endif %}
                {% include 'product_plus', product: product, image_size: ratio %}
              </div>
            {% endif %}
          {% endfor %}
          {% if shop.env == 1 and size == '' %}
            {% include 'mock' %}
          {% endif %}
      {% endcase %}
    </div>
  {% else %}
    {% if shop.env == 1 %}
      {% case max_count %}
        {% when 1 %}
          {% assign colMd="col-md-12" %}
        {% when 2 %}
          {% assign colMd="col-md-6" %}
        {% when 4 %}
          {% assign colMd="col-md-6"%}
      {% endcase %}
      <div class="row product_row common__product-row" id="55555555555555555">
        {% case max_count %}
          {% when 3 %}
            {% if arrangement == 'grid' %}
              {% for i in (1..3) %}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: default_product, image_size: '110%' %}
                </div>
              {% endfor %}
            {% else %}
              <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: default_product, image_size: '83%' %}</div>
              <div class="common__product-gap product_item {{arrangement}} col-md-3">
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
              </div>
            {% endif %}
          {% when 5 %}
            {% if arrangement == 'grid' %}
              {% for i in (1..2) %}
                <div class="common__product-gap product_item {{arrangement}} col-md-6">
                  {% include 'product_plus', product: default_product, image_size: '110%' %}
                </div>
              {% endfor %}
              {% for i in (1..3)%}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: default_product, image_size: '110%' %}
                </div>
              {% endfor %}
            {% else %}
              <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: default_product, image_size: '83%' %}</div>
              <div class="common__product-gap product_item {{arrangement}} col-md-3">
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
              </div>
              <div class="common__product-gap product_item {{arrangement}} col-md-6">{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
              <div class="common__product-gap product_item {{arrangement}} col-md-6">{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
            {% endif %}
          {% when 6 %}
            {% if arrangement == 'grid' %}
              {% for i in (1..6) %}
                <div class="common__product-gap product_item {{arrangement}} col-md-3">
                  {% include 'product_plus', product: default_product, image_size: '110%' %}
                </div>
              {% endfor %}
            {% else %}
              <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: default_product, image_size: '83%' %}</div>
              <div class="common__product-gap product_item {{arrangement}} col-md-3">
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
              </div>
              <div class="common__product-gap product_item {{arrangement}} col-md-3">
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
                <div>{% include 'product_plus', product: default_product, image_size: '110%' %}</div>
              </div>
              <div class="common__product-gap product_item {{arrangement}} col-md-8">{% include 'product_plus', product: default_product, image_size: '83%' %}</div>
            {% endif %}
          {% else %}
            {% for product in (1..max_count)%}
              <div class="common__product-gap product_item {{arrangement}} {{colMd}}">
                {% if max_count == 1 %}
                  {% assign ratio = '50%' %}
                {% else %}
                  {% assign ratio = '110%' %}
                {% endif %}
                {% include 'product_plus', product: default_product, image_size: ratio %}
              </div>
            {% endfor %}
            {% if shop.env == 1 and max_count == '' %}
              {% include 'mock' %}
            {% endif %}
        {% endcase %}
      </div>
    {% endif %}
  {% endif %}
</div>
</section>



