.review-product-item {
  flex: 0 0 25%;
  padding: 0 12px;
  position: relative; }

.review-product-item:after {
  content: "";
  position: absolute;
  width: 80%;
  height: 4px;
  bottom: 0;
  left: 10%; }

.review-product-item.on:after {
  background: #FFC700; }

.review-product-item .image-wrap {
  height: 280px;
